gaie(){return"\u06cc\u0627\u0646\u060c \u0628\u06c6 \u0647\u0646\u062f\u06ce \u0647\u06d5\u0645\u06cc \u0626\u06d5\u0648 \u06a9\u0627\u063a\u06d5\u0632\u06ce\u0646 \u062a\u0648 \u062f\u0641\u0631\u06ce\u06a9\u06d5\u06cc \u0628\u0628\u06cc\u0646\u06cc: \u06af\u0631\u0648\u0648\u067e\u06d5\u06a9\u0627 \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce \u062f\u06af\u06d5\u0644 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u06ce \u0686\u06ce\u0628\u06a9\u06d5\u060c \u067e\u0627\u0634\u0627\u0646 \u06a4\u06cc \u0644\u06cc\u0646\u06a9\u06cc \u06a4\u06d5\u06a9\u06d5 \u0648 \u0648\u06cc \u06af\u0631\u0648\u0648\u067e\u06cc \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u06d5. \u06a9\u0627\u063a\u06d5\u0632 \u062f\u06ce \u0628\u06c6 \u0647\u06d5\u0631\u062f\u0648\u0648\u06a9\u0627\u0646 \u062f \u06af\u0631\u0648\u0648\u067e\u06cc \u062f\u0627 \u06af\u06d5\u0647\u0646. \u062a\u0646\u06ce \u0626\u06ce\u06a9 \u0698 \u06a4\u0627\u0646 \u0647\u06d5\u0631\u062f\u0648\u0648 \u0644\u06cc\u0646\u06a9\u0627\u0646 \u0628\u06a9\u0627\u0631\u0628\u06cc\u0646\u06d5."},
aih(a,b){return a+" \xb7 \u0686\u0627\u06a4\u06d5\u0695\u06ce\u06cc Start (\u0644\u06cc\u0646\u06a9 \u0647\u06d5\u062a\u0627 "+b+" \u06a9\u0627\u0631 \u062f\u06a9\u06d5\u062a)"},
