a4H(a){return a+" \u2014 \u06a9\u06c6\u067e\u06cc\u06cc\u0627 \u062f\u0627\u062a\u0627\u06cc\u0627\u0646"},
a4D(a){return"\u06a9\u06c6\u067e\u06cc\u06cc\u06d5\u06a9\u0627 \u062a\u0646\u06ce-\u062e\u0648\u0627\u0646\u062f\u0646\u06ce \u0644 "+a+" \u0647\u0627\u062a\u06cc\u06d5 \u0686\u06ce\u06a9\u0631\u0646. \u0628\u06ce\u06cc \u0626\u06d5\u067e \u0648 \u0628\u06ce\u06cc \u0626\u06cc\u0646\u062a\u06d5\u0631\u0646\u06ce\u062a \u06a9\u0627\u0631 \u062f\u06a9\u06d5\u062a."},
ga4E(){return"\u06af\u06d5\u0695\u0627\u0646\u2026"},
a4G(a,b){return"\u0646\u06cc\u0634\u0627\u0646\u062f\u0627\u0646\u0627 "+a+" \u0698 "+b},
ga4F(){return"\u067e\u062a\u0631 \u0646\u06cc\u0634\u0627\u0646 \u0628\u062f\u06d5"},
ga4C(){return"\u0686 \u062a\u0634\u062a \u0644 \u06a4\u06ce\u0631\u06ce \u0646\u06cc\u0646\u0646."},
ga4f(){return"\u06a9\u06d5\u06cc\u0633"},
ga4s(){return"\u0645\u06ce\u0698\u0648\u0648\u06cc\u0627 \u0642\u06c6\u0646\u0627\u063a\u0627\u0646"},
