ga4v(){return"\u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631"},
ga4t(){return"\u067e\u0633\u0648\u0648\u0644\u06d5\u06cc\u06ce\u0646 \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u0627\u0646"},
